fn mk_filled_vec(n: usize, val: f32) -> Vec<f32> {
    vec![val; n]
}

fn lagval3d(
    x: Vec<f32>,
    y: Vec<f32>,
    z: Vec<f32>,
    c: Vec<Vec<Vec<f32>>>
) -> Vec<f32> {
    // Ensure inputs have the same (positive) length
    let n = x.len();
    debug_assert!(n > 0, "Input arrays must be non-empty");
    debug_assert!(y.len() == n, "x and y must have the same length");
    debug_assert!(z.len() == n, "x and z must have the same length");

    // Check if c is exactly 1×1×1
    if c.len() == 1
        && c[0].len() == 1
        && c[0][0].len() == 1
    {
        let coef = c[0][0][0];
        mk_filled_vec(n, coef)
    } else {
        mk_filled_vec(n, 0.0)
    }
}

